public static void verify(Context c) throws Exception {if(!ready(c))throw new IOException("Ephemeris not downloaded");String actual=hash(path(c)),saved=c.getSharedPreferences("ephemeris",0).getString("sha256","");if(!MessageDigest.isEqual(actual.getBytes("UTF-8"),saved.getBytes("UTF-8")))throw new IOException("Ephemeris SHA-256 changed");try(SolarAlarmEphemeris e=new SolarAlarmEphemeris(path(c))){} }
